	Users_DeleteUserTool   = newTool("users-delete_user_v1", `Deletes a user. DELETE /v1/{name=users/*} Soft delete: the user is marked deleted, disappears from List unless `+"`"+`show_deleted`+"`"+` is set, and is purged at `+"`"+`expire_time`+"`"+`. NOT_FOUND          no such user ABORTED            etag does not match PERMISSION_DENIED  caller may not delete it`, Users_DeleteUserSchemaJSON, Users_DeleteUserOutputSchemaJSON, nil, "", nil)
